create extension if not exists pgcrypto;
create type public.tournament_format as enum ('single_elimination','double_elimination');
create type public.tournament_status as enum ('draft','ready','active','paused','completed','archived','cancelled');
create type public.tournament_visibility as enum ('public','unlisted','private');
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(char_length(display_name) between 1 and 80),avatar_url text,locale text not null default 'es' check(locale in('es','en')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tournaments(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete restrict,name text not null check(char_length(name) between 1 and 120),slug text not null unique,description text check(char_length(description)<=2000),category text,format public.tournament_format not null default 'single_elimination',status public.tournament_status not null default 'draft',visibility public.tournament_visibility not null default 'unlisted',timezone text not null default 'UTC',scheduled_at timestamptz,max_participants integer not null default 32 check(max_participants between 2 and 256),best_of integer not null default 3 check(best_of>0 and best_of%2=1),random_seed bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1);
create table public.participants(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,user_id uuid references public.profiles on delete set null,display_name text not null check(char_length(display_name) between 1 and 80),seed integer not null check(seed>0),initial_position integer not null check(initial_position>0),created_at timestamptz not null default now(),unique(tournament_id,seed));
create table public.rounds(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,round_number integer not null check(round_number>0),name text not null,sequence integer not null,unique(tournament_id,sequence));
create table public.matches(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,round_id uuid not null references public.rounds on delete cascade,match_number integer not null,participant_one_id uuid references public.participants on delete restrict,participant_two_id uuid references public.participants on delete restrict,winner_id uuid references public.participants on delete restrict,loser_id uuid references public.participants on delete restrict,status text not null default 'pending' check(status in('pending','ready','in_progress','completed','review','void')),best_of integer not null check(best_of>0 and best_of%2=1),participant_one_score integer check(participant_one_score>=0),participant_two_score integer check(participant_two_score>=0),next_match_for_winner_id uuid references public.matches deferrable initially deferred,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,match_number));
create index tournaments_owner_updated_idx on public.tournaments(owner_id,updated_at desc);create index tournaments_public_idx on public.tournaments(updated_at desc) where visibility='public';create index participants_tournament_idx on public.participants(tournament_id);create index matches_tournament_round_idx on public.matches(tournament_id,round_id);
alter table public.profiles enable row level security;alter table public.tournaments enable row level security;alter table public.participants enable row level security;alter table public.rounds enable row level security;alter table public.matches enable row level security;
create policy "profiles readable by owner" on public.profiles for select using(auth.uid()=id);create policy "profiles editable by owner" on public.profiles for update using(auth.uid()=id);
create policy "visible tournaments readable" on public.tournaments for select using(visibility='public' or owner_id=auth.uid());create policy "owners create tournaments" on public.tournaments for insert with check(owner_id=auth.uid());create policy "owners update tournaments" on public.tournaments for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());create policy "owners delete tournaments" on public.tournaments for delete using(owner_id=auth.uid());
create policy "participants follow tournament visibility" on public.participants for select using(exists(select 1 from public.tournaments t where t.id=tournament_id and(t.visibility='public' or t.owner_id=auth.uid())));create policy "owners manage participants" on public.participants for all using(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid())) with check(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid()));
create policy "rounds follow tournament visibility" on public.rounds for select using(exists(select 1 from public.tournaments t where t.id=tournament_id and(t.visibility='public' or t.owner_id=auth.uid())));create policy "owners manage rounds" on public.rounds for all using(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid())) with check(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid()));
create policy "matches follow tournament visibility" on public.matches for select using(exists(select 1 from public.tournaments t where t.id=tournament_id and(t.visibility='public' or t.owner_id=auth.uid())));create policy "owners manage matches" on public.matches for all using(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid())) with check(exists(select 1 from public.tournaments t where t.id=tournament_id and t.owner_id=auth.uid()));
